class Squirrel:
    def __init__(self, name):
        self.name = name
        self.nuts = 0

    def gather(self, n):
        self.nuts += n
        return self.nuts

s = Squirrel("Hazel")
s.gather(3)
print(s.gather(2))

class Tree:
    def __init__(self, kind, height):
        self.kind = kind
        self.height = height

    def __str__(self):
        return f"{self.kind} ({self.height} m)"

print(Tree("oak", 20))

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."

class Squirrel(Animal):
    def speak(self):
        return "chitter"

for a in [Animal("rock"), Squirrel("Hazel")]:
    print(a.name, a.speak())

